L17_1.m_fTalkTime = 0.03
L17_1.m_Talk_JPN = "言った通り、オオカミがいないと黄金の木を消すことはできない。"
L17_1.m_Talk_ENG = "As I said, without the Wolf, there is no way to remove the Golden Tree."
L17_1.m_Talk_TWN = "我說過了，沒有狼就無法摧毀黃金樹。"
