L33_1 = {}
L33_1.m_CutScenKey_Talk = "EP15_ACT4_INTERLUDE18@20#Talk"
L33_1.m_CutScenProcessKey = 33
L33_1.m_CutScenID = 725
L33_1.m_CutScenStrID = "EP15_ACT4_INTERLUDE18"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_Face = "UNIT_SERIOUS"
L33_1.m_CharStrID = "RITA_ANAP_NULL_NULL"
L33_1.m_Pos = "C"
L33_1.m_Talk_KOREA = "그들은 낙원의 주민들과 달리 먼 세계에서 온 엑자일러들이야."
L33_1.m_fTalkTime = 0.03
L33_1.m_Talk_JPN = "彼らは楽園の住民とは違い、遠い世界から来たエグザイラーだ。"
L33_1.m_Talk_ENG = "Unlike the residents of the Promised Land, they are Exiles from distant worlds."
L33_1.m_Talk_TWN = "他們與樂園的居民不同，是來自遙遠世界的流放者。"
L33_1.m_Talk_DEU = "Unlike the residents of the Promised Land, they are Exiles from distant worlds."
L33_1.m_Talk_FRA = "Unlike the residents of the Promised Land, they are Exiles from distant worlds."
L34_1 = {}
L34_1.m_CutScenKey_Talk = "EP15_ACT4_INTERLUDE18@21#Talk"
L34_1.m_CutScenProcessKey = 34
L34_1.m_CutScenID = 725
L34_1.m_CutScenStrID = "EP15_ACT4_INTERLUDE18"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_CharStrID = "RITA_ANAP_NULL_NULL"
L34_1.m_Pos = "C"
L34_1.m_Talk_KOREA = "그리고 황금나무는 엑자일러의 존재를 말소시키는 일종의 척력을 발휘하지."
L34_1.m_fTalkTime = 0.03
L34_1.m_Talk_JPN = "そして黄金の木は世界の意志として、異なる性質を持つエグザイラーを追放しようとする、一種の斥力を発揮する。"
L34_1.m_Talk_ENG = "And the Golden Tree, as the Will of the World, exerts a kind of repulsive force that seeks to expel Exiles with different properties."
L34_1.m_Talk_TWN = "而黃金樹作為世界的意志，會發揮排斥力驅逐這些異質的流放者。"
L34_1.m_Talk_DEU = "And the Golden Tree, as the Will of the World, exerts a kind of repulsive force that seeks to expel Exiles with different properties."
L34_1.m_Talk_FRA = "And the Golden Tree, as the Will of the World, exerts a kind of repulsive force that seeks to expel Exiles with different properties."
