L39_1 = {}
L39_1.m_CutScenKey_Talk = "EP15_ACT4_INTERLUDE18@24#Talk"
L39_1.m_CutScenProcessKey = 39
L39_1.m_CutScenID = 725
L39_1.m_CutScenStrID = "EP15_ACT4_INTERLUDE18"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L39_1.m_Talk_KOREA = "세계가 엑자일러를 판단하는 기준은 적개심이나 위험성 같은 게 아닐세."
L39_1.m_fTalkTime = 0.03
L39_1.m_Talk_JPN = "世界がエグザイラーを判断する基準は、敵意や危険性などではない。"
L39_1.m_Talk_ENG = "The standard by which the world judges Exiles is not hostility or danger."
L39_1.m_Talk_TWN = "世界判斷流放者的標準不是敵意或危險性。"
L39_1.m_Talk_DEU = "The standard by which the world judges Exiles is not hostility or danger."
L39_1.m_Talk_FRA = "The standard by which the world judges Exiles is not hostility or danger."
L40_1 = {}
L40_1.m_CutScenKey_Talk = "EP15_ACT4_INTERLUDE18@25#Talk"
L40_1.m_CutScenProcessKey = 40
L40_1.m_CutScenID = 725
L40_1.m_CutScenStrID = "EP15_ACT4_INTERLUDE18"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L40_1.m_Talk_KOREA = "자신의 세계와 같은 성질을 가지고 있느냐, 그렇지 않느냐가 기준으로 작용할 뿐."
L40_1.m_fTalkTime = 0.03
L40_1.m_Talk_JPN = "自分の世界と同じ性質を持っているかどうか、が基準になる。"
L40_1.m_Talk_ENG = "What matters is whether they share the same nature as this world or not."
L40_1.m_Talk_TWN = "而是他們是否具有與這個世界相同的性質。"
L40_1.m_Talk_DEU = "What matters is whether they share the same nature as this world or not."
L40_1.m_Talk_FRA = "What matters is whether they share the same nature as this world or not."
L41_1 = {}
L41_1.m_CutScenKey_Talk = "EP15_ACT4_INTERLUDE18@26#Talk"
L41_1.m_CutScenProcessKey = 41
L41_1.m_CutScenID = 725
L41_1.m_CutScenStrID = "EP15_ACT4_INTERLUDE18"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L41_1.m_Talk_KOREA = "그러니, 자네가 연주를 통해 우리 엑자일러들에게 이 세계의 성질을 부여한다면..."
L41_1.m_fTalkTime = 0.03
L41_1.m_Talk_JPN = "だから、君が演奏で彼らにこの世界の性質を与えるんだ。"
L41_1.m_Talk_ENG = "Therefore, through your performance, you must grant them the nature of this world."
L41_1.m_Talk_TWN = "所以請透過演奏，賦予他們與這個世界相同的性質。"
L41_1.m_Talk_DEU = "Therefore, through your performance, you must grant them the nature of this world."
L41_1.m_Talk_FRA = "Therefore, through your performance, you must grant them the nature of this world."
