L42_1.m_CutScenProcessKey = 42
L42_1.m_CutScenID = 725
L42_1.m_CutScenStrID = "EP15_ACT4_INTERLUDE18"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L42_1.m_Talk_KOREA = "황금나무는 더 이상 그들의 존재를 밀어내지 않을 거야."
L42_1.m_fTalkTime = 0.03
L42_1.m_Talk_JPN = "黄金の木の斥力が、これ以上彼らの存在を拒まないように。"
L42_1.m_Talk_ENG = "So that the Golden Tree's repulsive force will no longer push their existence away."
L42_1.m_Talk_TWN = "讓黃金樹不再排斥他們的存在。"
