L4_1 = "BAND2_ANAP_NULL_NAME"
L3_1.m_CharStrID = L4_1
L4_1 = "황금나무는 우리가 이 순례길 끝에 낙원의 완성을 위한 연주를 할 수 있을 거라고 했습니다."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "黄金の木はこの巡礼の終わりに、楽園を完成するための演奏ができるだろうと言いました。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "The Golden Tree told us that at the end of this pilgrimage, we would be able to perform for the completion of the Promised Land."
L3_1.m_Talk_ENG = L4_1
L4_1 = "黃金樹說我們能在這段朝聖之旅的終點，完成拯救樂園的演奏。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "The Golden Tree told us that at the end of this pilgrimage, we would be able to perform for the completion of the Promised Land."
L3_1.m_Talk_DEU = L4_1
L4_1 = "The Golden Tree told us that at the end of this pilgrimage, we would be able to perform for the completion of the Promised Land."
L3_1.m_Talk_FRA = L4_1
