L5_1 = "EP15_ACT4_INTERLUDE18@69#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 104
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 725
L4_1.m_CutScenStrID = "EP15_ACT4_INTERLUDE18"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L5_1 = "BAND2_ANAP_NULL_NAME"
L4_1.m_CharStrID = L5_1
L5_1 = "그 연주는 분명... 누구의 희생으로도 더럽혀지지 않은 가장 고결한 음악이 될 것이라고도 했죠."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "その演奏はきっと……誰かの犠牲によって穢れていない、もっとも高潔な音楽になるとも。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "It also said that performance would surely become the most noble music of all... untouched by anyone's sacrifice."
L4_1.m_Talk_ENG = L5_1
L5_1 = "那場演奏……必定是沒有任何犧牲、最崇高的音樂。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "It also said that performance would surely become the most noble music of all... untouched by anyone's sacrifice."
L4_1.m_Talk_DEU = L5_1
L5_1 = "It also said that performance would surely become the most noble music of all... untouched by anyone's sacrifice."
L4_1.m_Talk_FRA = L5_1
