L5_1.m_CutScenID = 725
L5_1.m_CutScenStrID = "EP15_ACT4_INTERLUDE18"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L6_1 = "BAND3_ANAP_NULL_NAME"
L5_1.m_CharStrID = L6_1
L6_1 = "세상을 구한다는 명분으로 피를 묻혔던 어리석은 저희 악단은... 속죄를 위해 할 수 있는 마지막 연주를 기다렸어요."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "世界を救うという口実で手を血に染めた愚かな私たちの楽団は……贖罪のための最後の演奏を待っていました。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Our foolish orchestra, which stained its hands with blood in the name of saving the world... has been waiting for one final performance for the sake of atonement."
L5_1.m_Talk_ENG = L6_1
L6_1 = "我們這些曾以拯救世界之名沾滿鮮血的愚者樂團……一直在等待，為了贖罪所能演出的最後一場演奏。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "Our foolish orchestra, which stained its hands with blood in the name of saving the world... has been waiting for one final performance for the sake of atonement."
