L33_1 = "다치지 않은 사람들까지... 뭔가에 홀린 것처럼 나아가지 못하고 있어."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "怪我をしてない人まで……何かに憑かれたように動きが遅くなってるよ。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Even those who aren't injured... They're slowing down like they're under some kind of spell."
L32_1.m_Talk_ENG = L33_1
L33_1 = "連沒有受傷的人……好像被什麼迷惑，動作都變慢了。"
