L33_1.m_CharStrID = L34_1
L33_1.m_Pos = "C"
L34_1 = "자기 존재에 괴리가 생긴 거다. 최면에 걸린 것처럼 몸과 정신이 멀어지는 느낌이겠지."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "自分の存在と乖離が生じたんだ。催眠にかかったように、肉体と精神が離れるような感覚だろう。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Their sense of existence is starting to come apart. It must feel like their bodies and minds are drifting apart, as if they're under hypnosis."
L33_1.m_Talk_ENG = L34_1
L34_1 = "是自我存在出現偏差。就像被催眠一樣，身體與精神脫節。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "Their sense of existence is starting to come apart. It must feel like their bodies and minds are drifting apart, as if they're under hypnosis."
