L39_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L38_1.m_CharStrID = L39_1
L38_1.m_Pos = "L"
L39_1 = "아무리 테라브레인을 통해 인과율을 꿰뚫어보며 계획을 세웠다 해도... 우연히 스친 총알 한 발에 죽을 수도 있는 사람이라고."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "いくらテラブレインを使って因果律を見通し、計画を立てたとはいえ……偶然かすった一発の弾で死ぬかもしれない人よ。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "No matter how carefully he planned everything by seeing through causality with the Terrabrain... he's still someone who could die from a single stray bullet."
L38_1.m_Talk_ENG = L39_1
L39_1 = "即使能透過特拉大腦預測因果率、制定計畫……也可能被一顆偶然的子彈奪走性命。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "No matter how carefully he planned everything by seeing through causality with the Terrabrain... he's still someone who could die from a single stray bullet."
L38_1.m_Talk_DEU = L39_1
L39_1 = "No matter how carefully he planned everything by seeing through causality with the Terrabrain... he's still someone who could die from a single stray bullet."
L38_1.m_Talk_FRA = L39_1
