L41_1.m_Pos = "R"
L42_1 = "강하기 때문에 믿는 게 아니잖아."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "強いから信じているわけじゃないだろう。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "We don't trust him because he's strong."
