L42_1.m_CharStrID = L43_1
L42_1.m_Pos = "R"
L43_1 = "목적이 있다면 무슨 짓을 해서라도 이뤄내는 사람이니까 믿는 거지."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "目的があればどんな手を使ってでも成し遂げる人だから信じるんだ。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "We trust him because if he has a goal, he'll achieve it no matter what it takes."
L42_1.m_Talk_ENG = L43_1
L43_1 = "而是因為他會為了目標不擇手段。"
