L43_1.m_CharStrID = L44_1
L43_1.m_Pos = "R"
L44_1 = "그 수단이 한없이 악에 가까운 것이라 해도 망설이지 않을... 그런 사람이니까."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "たとえその手段が限りなく悪に近いものだとしても迷わず実行する……そんな人だから。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Because he's the kind of person who wouldn't hesitate... even if the means came dangerously close to evil."
L43_1.m_Talk_ENG = L44_1
L44_1 = "即使那個手段近乎作惡也毫不猶豫……他就是這樣的人。"
