L45_1.m_CharStrID = L46_1
L45_1.m_Pos = "C"
L46_1 = "그런데, 우리 앞을 막고 있는 저 실루엣들은 뭐지? 성벽처럼 늘어서 있는데."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "ところで、我々の行く手を塞いでいるあのシルエットはなんだ？　城壁のように並んでいるが。"
L45_1.m_Talk_JPN = L46_1
