L47_1 = "전방에 고위 신성 개체 다수 감지...! 식별 된 시그니처 파형에 따르면 소프라노로 추정됩니다!"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "前方に多数の高レベル神聖個体を感知……！　識別されたシグネチャー波形によると、ソプラノと推定されます！"
