L49_1.m_Pos = "L"
L50_1 = "하지만 저 수는 대체 뭐지? 마에스트로와의 전투 때도 저렇게 많지는 않았는데?"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "でもあの数はいったい……？　マエストロとの戦闘の時もこんなに多くはなかったのに。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "But why are there so many? There weren't even this many during the battle with Maestra."
L49_1.m_Talk_ENG = L50_1
L50_1 = "但數量怎麼會這麼多？我們和指揮家戰鬥時都沒這麼多。"
