L12_1.m_Pos = "C"
L13_1 = "그 나무는 내 심장에 박힌 것과 같은, 황금나무라 불리는 세상의 기둥."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "あの木は私の心臓に刺さっているものと同じ、黄金の木と呼ばれる世界の柱。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "That tree is the pillar of the world called the Golden Tree, the same one embedded in my heart."
L12_1.m_Talk_ENG = L13_1
L13_1 = "那棵樹是貫穿我心臟、名為黃金樹的世界支柱。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "That tree is the pillar of the world called the Golden Tree, the same one embedded in my heart."
L12_1.m_Talk_DEU = L13_1
L13_1 = "That tree is the pillar of the world called the Golden Tree, the same one embedded in my heart."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "EP15_ACT4_INTERLUDE18@141#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 213
L13_1.m_CutScenProcessKey = L14_1
