L14_1 = "UNIT_IDLE"
L13_1.m_Face = L14_1
L14_1 = "CURIAN_BORDER_NULL_FAKE"
L13_1.m_CharStrID = L14_1
L13_1.m_Pos = "C"
L14_1 = "우리도 먼 과거엔, 그 나무를 둘러싼 낙원에서 그 금빛 은총을 누리며 살았지."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "我々も遠い昔は、あの木を囲む楽園で、金色の恩寵を受けて暮らしていた。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Long ago, we too lived in a paradise surrounding that tree, receiving its golden grace."
L13_1.m_Talk_ENG = L14_1
L14_1 = "我們很久以前，也曾在那棵樹環繞的樂園中，享受那金色的恩寵。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "Long ago, we too lived in a paradise surrounding that tree, receiving its golden grace."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Long ago, we too lived in a paradise surrounding that tree, receiving its golden grace."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "EP15_ACT4_INTERLUDE18@142#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 214
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 725
