L15_1 = "ANDY_ATELIER_NULL_NICK"
L14_1.m_CharStrID = L15_1
L14_1.m_Pos = "C"
L15_1 = "황금나무와 아발론... 이 기억들은 전부 어디에서 온 거지?"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "黄金の木とアバロン……この記憶は全部どこから来たの？"
L14_1.m_Talk_JPN = L15_1
L15_1 = "The Golden Tree and Avalon... Where did all these memories come from?"
L14_1.m_Talk_ENG = L15_1
L15_1 = "黃金樹與阿瓦隆……這些記憶究竟從何而來呢？"
L14_1.m_Talk_TWN = L15_1
L15_1 = "The Golden Tree and Avalon... Where did all these memories come from?"
L14_1.m_Talk_DEU = L15_1
L15_1 = "The Golden Tree and Avalon... Where did all these memories come from?"
L14_1.m_Talk_FRA = L15_1
