L16_1 = "EP15_ACT4_INTERLUDE18@143#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 215
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 725
