L16_1 = "LEEJISOO_SIX_OFFICE_NULL"
L15_1.m_CharStrID = L16_1
L15_1.m_Pos = "C"
L16_1 = "이 세계의 기억을 덧씌움으로써- 세계로부터 추방 당하는 것을 막는다..."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "この世界の記憶を上書きすることで世界からの追放を防ぐ……"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Overlaying the memories of this world so that they wouldn't be expelled by the world..."
L15_1.m_Talk_ENG = L16_1
L16_1 = "透過覆寫世界的記憶－防止被世界驅逐……"
L15_1.m_Talk_TWN = L16_1
L16_1 = "Overlaying the memories of this world so that they wouldn't be expelled by the world..."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Overlaying the memories of this world so that they wouldn't be expelled by the world..."
L15_1.m_Talk_FRA = L16_1
