L17_1 = "LEEJISOO_SIX_OFFICE_NULL"
L16_1.m_CharStrID = L17_1
L16_1.m_Pos = "C"
L17_1 = "네가 말한 그 이론 뿐인 가설이, 아무래도 누군가에 의해 실현된 모양이군."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "お前が話したその理論上の仮説が、どうやら誰かによって実現されたようだな。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "It seems that hypothesis you mentioned, which existed only in theory, has now been realized by someone."
L16_1.m_Talk_ENG = L17_1
L17_1 = "看來你說的那個假設性的理論，已經被某人實現了。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "It seems that hypothesis you mentioned, which existed only in theory, has now been realized by someone."
L16_1.m_Talk_DEU = L17_1
