L21_1 = "EP15_ACT4_INTERLUDE18@146#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 220
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 725
