L21_1 = "CONDUCT_HARMONY_NULL_NULL"
L20_1.m_CharStrID = L21_1
L20_1.m_Pos = "L"
L20_1.m_bCharPinup = true
L21_1 = "기억을 기억으로 덮어 씌우는 대신, 두 가지 기억을 공존하게 만드는 조화의 선율이라니."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "記憶を記憶で上書きする代わりに、二つの記憶を共存させる、調和の旋律だなんて。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "A harmony that allows two memories to coexist instead of overwriting memory with memory... What an elegant melody."
L20_1.m_Talk_ENG = L21_1
L21_1 = "不是用記憶覆寫記憶，而是讓兩種記憶共存的和諧旋律。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "A harmony that allows two memories to coexist instead of overwriting memory with memory... What an elegant melody."
L20_1.m_Talk_DEU = L21_1
L21_1 = "A harmony that allows two memories to coexist instead of overwriting memory with memory... What an elegant melody."
