L23_1 = "EP15_ACT4_INTERLUDE18@147#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 222
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 725
L22_1.m_CutScenStrID = "EP15_ACT4_INTERLUDE18"
L22_1.m_bWaitClick = true
