L23_1 = "m_bLooseShake"
L22_1[L23_1] = true
L22_1.m_Face = "UNIT_DESPAIR"
L22_1.m_CharStrID = "AGENT_GRONIA_WHITE_NAME"
L22_1.m_Pos = "R"
L22_1.m_bCharPinup = true
L22_1.m_bCharPinupEasingTime = 0.3
L23_1 = "...그 사람 말이 맞아. 음악 그 자체엔 악의도, 선의도 없어."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "……あの人の言う通りだよ。音楽そのものには悪意も善意もない。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "...He was right. Music itself holds neither malice nor goodwill."
L22_1.m_Talk_ENG = L23_1
L23_1 = "……他說得沒錯，音樂本身沒有善也沒有惡。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "...He was right. Music itself holds neither malice nor goodwill."
L22_1.m_Talk_DEU = L23_1
L23_1 = "...He was right. Music itself holds neither malice nor goodwill."
L22_1.m_Talk_FRA = L23_1
