L24_1 = "EP15_ACT4_INTERLUDE18@148#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 223
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 725
L23_1.m_CutScenStrID = "EP15_ACT4_INTERLUDE18"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L24_1 = "m_bLooseShake"
L23_1[L24_1] = true
L23_1.m_CharStrID = "AGENT_GRONIA_WHITE_NAME"
L23_1.m_Pos = "R"
L23_1.m_bCharPinup = true
L24_1 = "그렇기 때문에, 순수를 버리고 악의에 물든 우리 손으로도... 누군가를 구하는 이 궤변스러운 선율을 자아낼 수 있는 거지."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "だからこそ純粋さを捨てて悪意に染まってしまった私たちの手でも……誰かを救うという、この矛盾した旋律を奏でることができる。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "That's why even with hands like ours, stained after abandoning purity and sinking into malice... We can still bring forth this paradoxical melody that saves someone."
L23_1.m_Talk_ENG = L24_1
L24_1 = "正因如此，即使是拋棄純粹、沾染惡意的我們……也能奏出這種詭譎卻能拯救他人的旋律。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "That's why even with hands like ours, stained after abandoning purity and sinking into malice... We can still bring forth this paradoxical melody that saves someone."
L23_1.m_Talk_DEU = L24_1
L24_1 = "That's why even with hands like ours, stained after abandoning purity and sinking into malice... We can still bring forth this paradoxical melody that saves someone."
L23_1.m_Talk_FRA = L24_1
