L26_1 = "EP15_ACT4_INTERLUDE18@149#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 225
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 725
L25_1.m_CutScenStrID = "EP15_ACT4_INTERLUDE18"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L26_1 = "m_bLooseShake"
L25_1[L26_1] = true
L26_1 = "CONDUCT_HARMONY_NULL_NULL"
L25_1.m_CharStrID = L26_1
L26_1 = "멘탈 프린팅은 수많은 희생으로 빚어진 저주받은 기술. 그 힘으로 어떤 희망 찬 기적을 연주한들, 그것이 속죄가 되진 못하겠죠."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "メンタル・プリンティングは多くの犠牲によって作り上げられた呪われた技術。その力でどんなに希望に満ちた奇跡を起こしたとて、それが贖罪にはなりません。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Mental Printing is a cursed technique forged through countless sacrifices. No matter what hopeful miracle you perform with that power, it can't become atonement."
L25_1.m_Talk_ENG = L26_1
L26_1 = "智力複印是由無數犧牲構築的詛咒技術。即使憑藉這力量演奏出希望的奇蹟，也無法稱之為贖罪。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "Mental Printing is a cursed technique forged through countless sacrifices. No matter what hopeful miracle you perform with that power, it can't become atonement."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Mental Printing is a cursed technique forged through countless sacrifices. No matter what hopeful miracle you perform with that power, it can't become atonement."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "EP15_ACT4_INTERLUDE18@150#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 226
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 725
L26_1.m_CutScenStrID = "EP15_ACT4_INTERLUDE18"
L26_1.m_bWaitClick = true
