L27_1 = "m_bLooseShake"
L26_1[L27_1] = true
L26_1.m_CharStrID = "AGENT_GRONIA_WHITE_NAME"
L27_1 = "애초에 속죄 따위엔 관심 없어."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "そもそも贖罪になんて興味はないの。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "I was never interested in atonement in the first place."
L26_1.m_Talk_ENG = L27_1
L27_1 = "我本來就對贖罪沒興趣。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "I was never interested in atonement in the first place."
L26_1.m_Talk_DEU = L27_1
L27_1 = "I was never interested in atonement in the first place."
L26_1.m_Talk_FRA = L27_1
