L28_1 = "EP15_ACT4_INTERLUDE18@151#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 227
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 725
L27_1.m_CutScenStrID = "EP15_ACT4_INTERLUDE18"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L28_1 = "m_bLooseShake"
L27_1[L28_1] = true
L27_1.m_CharStrID = "AGENT_GRONIA_WHITE_NAME"
L28_1 = "이 저주 받은 선율이 희생 대신 구원을 가져올 수만 있다면..."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "この呪われた旋律が犠牲の代わりに、救いをもたらすことができれば……"
L27_1.m_Talk_JPN = L28_1
L28_1 = "If this cursed melody can bring salvation instead of sacrifice..."
L27_1.m_Talk_ENG = L28_1
L28_1 = "只要這詛咒般的旋律能帶來救贖而不是犧牲……"
L27_1.m_Talk_TWN = L28_1
L28_1 = "If this cursed melody can bring salvation instead of sacrifice..."
L27_1.m_Talk_DEU = L28_1
L28_1 = "If this cursed melody can bring salvation instead of sacrifice..."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "EP15_ACT4_INTERLUDE18@152#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 228
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 725
L28_1.m_CutScenStrID = "EP15_ACT4_INTERLUDE18"
L28_1.m_bWaitClick = true
