L29_1 = "m_bLooseShake"
L28_1[L29_1] = true
L28_1.m_CharStrID = "AGENT_GRONIA_WHITE_NAME"
L29_1 = "...내 영혼은 영원히 더럽혀진 채로 남아도 돼."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
