L40_1.m_CharStrID = L41_1
L40_1.m_Pos = "R"
L41_1 = "그 아이는 마왕의 파편을 몸에 심은 뒤로, 과거의 모든 기억을 잃었거든."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "あの子は魔王の破片を体に宿して、過去の記憶を全部なくしたからね。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "After she embedded the Demon Lord's Fragment into her body, she lost all memories of her past."
L40_1.m_Talk_ENG = L41_1
L41_1 = "因為在她體內植入魔王的碎片後，她失去了所有過去的記憶。"
