L43_1 = "전 어쩌다... 지금껏 모르가나의 존재를 잊고 살았던 걸까요?"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "私はどうして今までモルガナの存在を忘れていたんでしょうか。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Then how did I... forget about Morgana all this time?"
L42_1.m_Talk_ENG = L43_1
L43_1 = "我為什麼……至今都忘記了莫甘娜的存在？"
L42_1.m_Talk_TWN = L43_1
L43_1 = "Then how did I... forget about Morgana all this time?"
