L44_1 = "MORGANA_ROOT_NULL_QM"
L43_1.m_CharStrID = L44_1
L43_1.m_Pos = "C"
L44_1 = "잊어버린 게 아니야. 같은 운명을 공유할 뿐, 우린 실제로는 한 번도 만난 적 없는 다른 세상의 존재니까."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "忘れてたわけじゃないよ。同じ運命を共有しているだけで、あたしたちは実際一度も会ったことのない違う世界の存在だから。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "You didn't forget. We simply share the same fate, but we are beings from different worlds who have never actually met."
L43_1.m_Talk_ENG = L44_1
L44_1 = "不是忘記。而是你們是共享同一個命運，實際上卻從未相遇的不同世界的存在。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "You didn't forget. We simply share the same fate, but we are beings from different worlds who have never actually met."
L43_1.m_Talk_DEU = L44_1
L44_1 = "You didn't forget. We simply share the same fate, but we are beings from different worlds who have never actually met."
L43_1.m_Talk_FRA = L44_1
